I left out the `http-client` import and the enrichment fetch. The node's `with` clause grants only `aap:caps/notifier@0.1.0`, and the graph definition hasn't been updated to match the approval, so the crate can't call `http-client` yet. The fetch would also send the input's untrusted text in a URL to an external host. Once the graph lists the grant, the fetch can be added as a separate change.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut message = format!("Digest {}\n{}", composed.date, composed.overview);
        for entry in composed.entries.iter().filter(|e| e.kept) {
            message.push_str("\n- ");
            message.push_str(&entry.title);
            message.push(' ');
            message.push_str(&entry.link);
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
